import sys


def main():
    args = sys.argv[1:]
    flags = []
    filepath = None

    i = 0
    while i < len(args):
        arg = args[i]
        if arg.startswith("-") and not arg.startswith("--"):
            for ch in arg[1:]:
                if ch in ("l", "w", "c"):
                    flags.append(ch)
                else:
                    print(f"wc: invalid option -- '{ch}'", file=sys.stderr)
                    sys.exit(2)
        elif filepath is None:
            filepath = arg
        else:
            print("wc: extra file argument", file=sys.stderr)
            sys.exit(1)
        i += 1

    # Default to all three flags when none given
    if not flags:
        flags = ["l", "w", "c"]

    # Fixed output order: lines, words, characters
    show_lines = "l" in flags
    show_words = "w" in flags
    show_chars = "c" in flags

    if filepath is None or filepath == "-":
        data = sys.stdin.buffer.read()
    else:
        with open(filepath, "rb") as f:
            data = f.read()

    count_lines = data.count(b"\n")
    # A final line without trailing newline still counts as a line
    if data and not data.endswith(b"\n"):
        count_lines += 1
    count_words = len(data.split())
    count_chars = len(data)

    parts = []
    if show_lines:
        parts.append(str(count_lines))
    if show_words:
        parts.append(str(count_words))
    if show_chars:
        parts.append(str(count_chars))

    print(" ".join(parts))


if __name__ == "__main__":
    main()

